<script setup lang="ts">
import {ref} from 'vue'
import MissionTeamProposal from './MissionTeamProposal.vue'
import AppModal from './AppModal.vue'
import {request} from '@/services/quality'
export interface Mission {id:number;title:string;scope:string;starts_on:string;ends_on:string;status:string;version:number;decision_reason:string|null}
const props=defineProps<{requestId:number;requestVersion:number;mission?:Mission|null;coordinator?:boolean;ready?:boolean;submitted:boolean}>()
const emit=defineEmits<{saved:[]}>()
const open=ref(false),busy=ref(false),confirmed=ref(false),error=ref(''),reason=ref(''),decision=ref('accepted')
const form=ref({title:'',scope:'',starts_on:'',ends_on:''})
const labels:Record<string,string>={proposed:'En attente de l’accord de l’officine',accepted:'Acceptée par l’officine',refused:'Refusée par l’officine',cancelled:'Annulée par retrait de la demande'}
function start(value:string){decision.value=value;error.value='';confirmed.value=false;reason.value='';open.value=true}
async function save(){busy.value=true;error.value='';try{if(props.coordinator)await request(`/support/intake/${props.requestId}/propose-mission`,'POST',{...form.value,version:props.requestVersion});else await request(`/support/requests/${props.requestId}/mission-decision`,'POST',{version:props.mission!.version,decision:decision.value,confirmed:confirmed.value,...(decision.value==='refused'?{reason:reason.value}:{})});open.value=false;emit('saved')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><div class="form-body"><h3>Proposition de mission</h3><template v-if="mission"><dl class="application-summary"><dt>Intitulé</dt><dd>{{mission.title}}</dd><dt>Périmètre proposé</dt><dd style="white-space:pre-wrap">{{mission.scope}}</dd><dt>Période proposée</dt><dd>{{mission.starts_on}} → {{mission.ends_on}}</dd><dt>État</dt><dd>{{labels[mission.status]||mission.status}}</dd><dt>Motif de refus</dt><dd>{{mission.decision_reason||'—'}}</dd></dl><div v-if="!coordinator&&submitted&&mission.status==='proposed'" class="heading-actions"><button class="button primary" @click="start('accepted')">Accepter la proposition</button><button class="button secondary" @click="start('refused')">Refuser la proposition</button></div></template><button v-else-if="coordinator&&ready&&submitted" class="button primary" @click="start('propose')">Proposer une mission</button><p v-else>Aucune proposition de mission à ce stade.</p><MissionTeamProposal v-if="coordinator&&mission&&['accepted','active','suspended'].includes(mission.status)" :request-id="requestId" @saved="emit('saved')"/><RouterLink v-if="!coordinator&&mission" class="text-link" to="/dashboard/missions-accompagnement">Ouvrir mon espace missions</RouterLink><p class="module-disclaimer">L’accord de l’officine ne donne aucun accès aux données. Les accompagnateurs et leurs permissions nécessitent une approbation distincte. La planification des interventions n’est pas encore connectée.</p></div>
<AppModal v-model="open" :title="coordinator?'Proposer une mission':decision==='accepted'?'Accepter la proposition ?':'Refuser la proposition ?'" :busy="busy" size="wide"><form id="support-mission-form" class="form-body correction-form" @submit.prevent="save"><p v-if="error" class="alert error" role="alert">{{error}}</p><template v-if="coordinator"><label>Intitulé de mission<input v-model="form.title" required maxlength="180"/></label><label>Périmètre de mission<textarea v-model="form.scope" required maxlength="5000" rows="5"/></label><label>Début proposé<input v-model="form.starts_on" required type="date"/></label><label>Fin proposée<input v-model="form.ends_on" required type="date" :min="form.starts_on"/></label><p>La proposition sera transmise à l’officine pour décision. Elle ne démarre pas la mission.</p></template><template v-else><p>{{mission?.title}} · {{mission?.starts_on}} → {{mission?.ends_on}}</p><label v-if="decision==='refused'">Motif de refus obligatoire<textarea v-model="reason" required maxlength="2000" rows="4"/></label><label class="checkbox-label"><input v-model="confirmed" type="checkbox" required/>Je confirme explicitement {{decision==='accepted'?'l’acceptation':'le refus'}} de cette proposition.</label><p>Aucun accès aux autres données de l’officine ne sera accordé par cette décision.</p></template></form><template #footer><button class="button secondary" :disabled="busy" @click="open=false">Annuler</button><button class="button primary" :disabled="busy" form="support-mission-form" type="submit">{{coordinator?'Transmettre la proposition':'Confirmer la décision'}}</button></template></AppModal></template>
